#include "stm32f411xe.h"
#include <stm32f4xx.h>
#include <stm32f4xx.h>
#include <stdint.h>
 
//Cabecera de funcion 
void init_hardware (void);

int main(void){
    //aqui llamamos a la funcion, para que se ejecute el codigo que ponemos abajo del main
    init_hardware();

    while (1) {
        if (SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk) {
            GPIOB->ODR ^= GPIO_ODR_OD8; //Cambiar el estado del led
            GPIOB->ODR ^= GPIO_ODR_OD9; //Cambiar el estado del led
            GPIOB->ODR ^= GPIO_ODR_OD6; //Cambiar el estado del led
        
        }
    
    }

}

// Lo que hace la funcion
void init_hardware(void){

    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN; //Habilitar la señal de reloj  

    //verde 
    GPIOB->MODER &= ~(GPIO_MODER_MODE8); //Limpiar bits de modo para PB8
    GPIOB->MODER |= (GPIO_MODER_MODE8); //Configurar PB8 

    GPIOB->OTYPER &= ~GPIO_OTYPER_OT8; //Configurar PB8 como salida 
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8); //Configurar PB8 como 
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_1); //Configurar PB8 como 

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8); // Configurar PB8 para que quede sin pull-up y pull-down

    GPIOB->ODR &= ~(GPIO_ODR_OD8); //Inicializar PB8 en bajo 
    GPIOB->ODR |= (GPIO_ODR_OD8); //Inicializar PB8 en alto

    //Amarillo 
    GPIOB->MODER &= ~(GPIO_MODER_MODE9); //Limpiar bits de modo para PB8
    GPIOB->MODER |= (GPIO_MODER_MODE9); //Configurar PB9 

    GPIOB->OTYPER &= ~GPIO_OTYPER_OT9; //Configurar PB9 como salida 
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED9); //Configurar PB9 como 
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED9_1); //Configurar PB9 como 

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD9); // Configurar PB9 para que quede sin pull-up y pull-down

    GPIOB->ODR &= ~(GPIO_ODR_OD9); //Inicializar PB9 en bajo 
    GPIOB->ODR |= (GPIO_ODR_OD9); //Inicializar PB9 en alto


    //Rojo 
    GPIOB->MODER &= ~(GPIO_MODER_MODE6); //Limpiar bits de modo para PB6
    GPIOB->MODER |= (GPIO_MODER_MODE6); //Configurar PB6

    GPIOB->OTYPER &= ~GPIO_OTYPER_OT6; //Configurar PB6 como salida 
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED6); //Configurar PB6 como 
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED6_1); //Configurar PB6 como 

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD6); // Configurar PB6 para que quede sin pull-up y pull-down

    GPIOB->ODR &= ~(GPIO_ODR_OD6); //Inicializar PB8 en bajo 
    GPIOB->ODR |= (GPIO_ODR_OD6); //Inicializar PB6 en alto


    SysTick->LOAD = 16000000 - 1 ;// cargar el valor de recarga para 1s
    SysTick->VAL = 0; //Reiniciar el valor actual del contador 

    SysTick->CTRL |= SysTick_CTRL_CLKSOURCE_Msk; // Seleccionar el 
    SysTick->CTRL |= SysTick_CTRL_ENABLE_Msk;//Habilitar el contador 
     


}

